insert into fitmatch_taxonomy.category_app_mappings(decision_id,app_category_code,app_detail_code,current_comparison_family,current_length_type,mapping_status,transformation_rule,lossiness,app_taxonomy_version,comparison_policy_version)
select d.id,v.app_category,v.app_detail,v.current_family,v.length_type,v.mapping_status,v.rule,v.lossiness,'fitmatch-current-2026-08-03','taxonomy-final-2026-08-03'
from v join fitmatch_taxonomy.source_categories c on c.source_snapshot_id=v.snapshot_id and c.source_code=v.source_code and c.external_category_id=v.external_id and c.target=v.target join fitmatch_taxonomy.classification_decisions d on d.source_category_id=c.id and d.policy_version='taxonomy-final-2026-08-03' and d.decision_status='confirmed'
on conflict(decision_id) do nothing;
commit;
